const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const g = Array.from({ length: n + 1 }, () => []);
const rg = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < m; i++) {
  const u = tok[2 + 2 * i], v = tok[3 + 2 * i];
  g[u].push(v);
  rg[v].push(u);
}
const seen = new Array(n + 1).fill(false), nxt = new Array(n + 1).fill(0);
const order = [];
for (let s = 1; s <= n; s++) {
  if (seen[s]) continue;
  seen[s] = true;
  const stack = [s];
  while (stack.length) {
    const v = stack[stack.length - 1];
    if (nxt[v] < g[v].length) {
      const to = g[v][nxt[v]++];
      if (!seen[to]) { seen[to] = true; stack.push(to); }
    } else {
      stack.pop();
      order.push(v);
    }
  }
}
const label = new Array(n + 1).fill(0);
for (let i = order.length - 1; i >= 0; i--) {
  const s = order[i];
  if (label[s]) continue;
  label[s] = s;
  const members = [s], stack = [s];
  while (stack.length) {
    const v = stack.pop();
    for (const to of rg[v]) {
      if (!label[to]) { label[to] = s; members.push(to); stack.push(to); }
    }
  }
  const low = Math.min(...members);
  for (const v of members) label[v] = low;
}
console.log(label.slice(1).join(" "));

