import java.io.*;
import java.util.*;

public class Main {
    static List<Integer>[] g, rg;
    static boolean[] seen;
    static int[] label;
    static List<Integer> order = new ArrayList<>();

    static void dfs1(int v) {
        seen[v] = true;
        for (int to : g[v]) if (!seen[to]) dfs1(to);
        order.add(v);
    }

    static void dfs2(int v, int root, List<Integer> members) {
        label[v] = root;
        members.add(v);
        for (int to : rg[v]) if (label[to] == 0) dfs2(to, root, members);
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        g = new List[n + 1];
        rg = new List[n + 1];
        for (int i = 0; i <= n; i++) { g[i] = new ArrayList<>(); rg[i] = new ArrayList<>(); }
        for (int i = 0; i < m; i++) {
            in.nextToken();
            int u = (int) in.nval;
            in.nextToken();
            int v = (int) in.nval;
            g[u].add(v);
            rg[v].add(u);
        }
        seen = new boolean[n + 1];
        label = new int[n + 1];
        for (int s = 1; s <= n; s++) if (!seen[s]) dfs1(s);
        for (int i = order.size() - 1; i >= 0; i--) {
            int s = order.get(i);
            if (label[s] != 0) continue;
            List<Integer> members = new ArrayList<>();
            dfs2(s, s, members);
            int low = Collections.min(members);
            for (int v : members) label[v] = low;
        }
        StringBuilder out = new StringBuilder();
        for (int v = 1; v <= n; v++) out.append(label[v]).append(v < n ? " " : "\n");
        System.out.print(out);
    }
}

