    seen[v] = true;
    for (int to : g[v]) if (!seen[to]) dfs1(to);
    order_.push_back(v);
}
void dfs2(int v, int root, vector<int>& members) {
    label_[v] = root;
    members.push_back(v);
    for (int to : rg[v]) if (!label_[to]) dfs2(to, root, members);
}

