    g.assign(n + 1, {});
    rg.assign(n + 1, {});
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        g[u].push_back(v);
        rg[v].push_back(u);
    }
    seen.assign(n + 1, false);
    label_.assign(n + 1, 0);
    for (int s = 1; s <= n; s++) if (!seen[s]) dfs1(s);
    for (int i = (int)order_.size() - 1; i >= 0; i--) {
        int s = order_[i];
        if (label_[s]) continue;
        vector<int> members;
        dfs2(s, s, members);
